+static bool IsBugproneBigIntLooseEquality(ETSChecker *checker, Type *leftType, Type *rightType)
+{
+    leftType = GetComparableLooseEqualityType(checker, leftType);
+    rightType = GetComparableLooseEqualityType(checker, rightType);
+    if (leftType == nullptr || rightType == nullptr) {
+        return false;
+    }
+
+    bool leftIsBigInt = leftType->IsETSBigIntType();
+    bool rightIsBigInt = rightType->IsETSBigIntType();
+    return (leftIsBigInt && checker->CheckIfNumeric(rightType)) || (rightIsBigInt && checker->CheckIfNumeric(leftType));
+}
+
+static bool IsBugproneCharLooseEquality(ETSChecker *checker, Type *leftType, Type *rightType)
+{
+    leftType = GetComparableLooseEqualityType(checker, leftType);
+    rightType = GetComparableLooseEqualityType(checker, rightType);
+    if (leftType == nullptr || rightType == nullptr) {
+        return false;
+    }
+
+    return (leftType->IsCharType() && checker->CheckIfNumeric(rightType)) ||
+           (rightType->IsCharType() && checker->CheckIfNumeric(leftType));
+}
+
+void ETSChecker::MaybeReportBugproneLooseEquality(ir::Expression *expr, lexer::TokenType operationType, Type *leftType,
+                                                  Type *rightType)
+{
+    if (!IsLooseEqualityWarningOp(operationType) || expr == nullptr || !expr->IsBinaryExpression() ||
+        leftType == nullptr || rightType == nullptr || IsTypeError(leftType) || IsTypeError(rightType)) {
+        return;
+    }
+
+    auto *binExpr = expr->AsBinaryExpression();
+    if (!ShouldReportWarning(binExpr, ETSWarnings::ETS_BOOST_EQUALITY_STATEMENT)) {
+        return;
+    }
+
+    if (IsBugproneBigIntLooseEquality(this, leftType, rightType)) {
+        DiagnosticEngine().LogDiagnostic(diagnostic::BIGINT_BUGPRONE_LOOSEEQUAL, util::DiagnosticMessageParams {},
+                                         binExpr->Start());
+    }
+
+    if (IsBugproneCharLooseEquality(this, leftType, rightType)) {
+        DiagnosticEngine().LogDiagnostic(diagnostic::CHAR_BUGPRONE_LOOSEEQUAL, util::DiagnosticMessageParams {},
+                                         binExpr->Start());
+    }
+}
