static Type *BinaryGetPromotedType(ETSChecker *checker, Type *left, Type *right, bool const promote)
{
    Type *const unboxedL = TryConvertToPrimitiveType(checker, left);
    Type *const unboxedR = TryConvertToPrimitiveType(checker, right);
    if (unboxedL == nullptr || unboxedR == nullptr) {
        return nullptr;
    }

    Type *typeL = left;
    Type *typeR = right;

    bool const bothBoxed = !typeL->IsETSPrimitiveType() && !typeR->IsETSPrimitiveType();

    if (!promote) {
        return typeR;
    }

    if (!bothBoxed) {
        if (unboxedL->IsETSEnumType() || unboxedR->IsETSEnumType()) {
            return nullptr;
        }
        if (!typeL->IsETSPrimitiveType()) {
            typeL = checker->MaybeUnboxType(typeL);
        }
        if (!typeR->IsETSPrimitiveType()) {
            typeR = checker->MaybeUnboxType(typeR);
        }
    }

    if (checker->CheckIfNumeric(typeL) && checker->CheckIfNumeric(typeR)) {
        return EffectiveTypeOfNumericOp(checker, typeL, typeR);
    }
    if (checker->CheckIfNumeric(typeR)) {
        return typeR;
    }

    return typeL;
}

static bool IsLooseEqualityWarningOp(lexer::TokenType op)
{
    return op == lexer::TokenType::PUNCTUATOR_EQUAL || op == lexer::TokenType::PUNCTUATOR_NOT_EQUAL;
}

static Type *GetComparableLooseEqualityType(ETSChecker *checker, Type *type)
{
    if (type == nullptr || IsTypeError(type)) {
        return nullptr;
    }

    return checker->GetNormalizedType(checker->GetNonConstantType(checker->MaybeUnboxType(type)));
}

bool ETSChecker::CheckBinaryOperatorForBigInt(Type *left, Type *right, lexer::TokenType op)
{
    if ((left == nullptr) || (right == nullptr)) {
        return false;
    }

    // Allow operations between BigInt and numeric types - number will be converted to BigInt
    bool leftIsBigInt = left->IsETSBigIntType();
    bool rightIsBigInt = right->IsETSBigIntType();
    // Allow if either operand is BigInt.
    // The non-BigInt operand will be converted to BigInt during lowering.
    if ((leftIsBigInt && CheckIfNumeric(right)) || (rightIsBigInt && CheckIfNumeric(left))) {
        switch (op) {
            case lexer::TokenType::PUNCTUATOR_GREATER_THAN:
            case lexer::TokenType::PUNCTUATOR_LESS_THAN:
            case lexer::TokenType::PUNCTUATOR_GREATER_THAN_EQUAL:
            case lexer::TokenType::PUNCTUATOR_LESS_THAN_EQUAL:
            case lexer::TokenType::PUNCTUATOR_EQUAL:
            case lexer::TokenType::PUNCTUATOR_NOT_EQUAL:
            case lexer::TokenType::PUNCTUATOR_STRICT_EQUAL:
            case lexer::TokenType::PUNCTUATOR_NOT_STRICT_EQUAL:
                return true;
            default:
                break;
        }
    }

    if (!leftIsBigInt || !rightIsBigInt) {
        return false;
    }

    switch (op) {
        case lexer::TokenType::KEYW_INSTANCEOF:
        case lexer::TokenType::PUNCTUATOR_UNSIGNED_RIGHT_SHIFT:
            // This is handled in the main CheckBinaryOperator function
            return false;
        default:
            break;
    }

    return true;
}

static bool IsBugproneBigIntLooseEquality(ETSChecker *checker, Type *leftType, Type *rightType)
{
    leftType = GetComparableLooseEqualityType(checker, leftType);
    rightType = GetComparableLooseEqualityType(checker, rightType);
    if (leftType == nullptr || rightType == nullptr) {
        return false;
    }

    bool leftIsBigInt = leftType->IsETSBigIntType();
    bool rightIsBigInt = rightType->IsETSBigIntType();
    return (leftIsBigInt && checker->CheckIfNumeric(rightType)) || (rightIsBigInt && checker->CheckIfNumeric(leftType));
}

static bool IsBugproneCharLooseEquality(ETSChecker *checker, Type *leftType, Type *rightType)
{
    leftType = GetComparableLooseEqualityType(checker, leftType);
    rightType = GetComparableLooseEqualityType(checker, rightType);
    if (leftType == nullptr || rightType == nullptr) {
        return false;
    }

    return (leftType->IsCharType() && checker->CheckIfNumeric(rightType)) ||
           (rightType->IsCharType() && checker->CheckIfNumeric(leftType));
}

void ETSChecker::MaybeReportBugproneLooseEquality(ir::Expression *expr, lexer::TokenType operationType, Type *leftType,
                                                  Type *rightType)
{
    if (!IsLooseEqualityWarningOp(operationType) || expr == nullptr || !expr->IsBinaryExpression() ||
        leftType == nullptr || rightType == nullptr || IsTypeError(leftType) || IsTypeError(rightType)) {
        return;
    }

    auto *binExpr = expr->AsBinaryExpression();
    if (!ShouldReportWarning(binExpr, ETSWarnings::ETS_BOOST_EQUALITY_STATEMENT)) {
        return;
    }

    if (IsBugproneBigIntLooseEquality(this, leftType, rightType)) {
        DiagnosticEngine().LogDiagnostic(diagnostic::BIGINT_BUGPRONE_LOOSEEQUAL, util::DiagnosticMessageParams {},
                                         binExpr->Start());
    }

    if (IsBugproneCharLooseEquality(this, leftType, rightType)) {
        DiagnosticEngine().LogDiagnostic(diagnostic::CHAR_BUGPRONE_LOOSEEQUAL, util::DiagnosticMessageParams {},
                                         binExpr->Start());
    }
}

