  let d: double = 65.0
  let d2: double = 65.5
  let l: long = 65
  let b: byte = 65
  let s: short = 65
  if (!(c == f)) { return 1 }
  if (!(f == c)) { return 2 }
  if (!(c == d)) { return 3 }
  if (!(d == c)) { return 4 }
  if (c == d2) { return 5 }
  if (!(c == l)) { return 6 }
  if (!(c == b)) { return 7 }
  if (!(c == s)) { return 8 }
  if (!(c === d)) { return 9 }
  if (c !== d) { return 10 }
  return 0
}
EOF
